import { ref, shallowRef, computed, effect } from 'vue';

const N = 100_000;
const gc = globalThis.gc;
const heap = () => { gc(); gc(); return process.memoryUsage().heapUsed; };

function measure(label, make, touch = false) {
  const hold = new Array(N);
  const before = heap();
  for (let i = 0; i < N; i++) hold[i] = make(i);
  if (touch) for (let i = 0; i < N; i++) void hold[i].value;
  const after = heap();
