350	 *
351	 * This is made so that the defaults can be declared "as they are"
352	 * without requiring objects to be function callbacks returning an object.
353	 *
354	 * // You don't need to wrap objects in () => ({ nest: { nest :{} } })
355	 * // You can just delcare them normally.
356	 * const defaults = {
357	 *    nest: {
358	 *      nest
359	 *    }
360	 * }
361	 *
362	 * This function will create the Vue expected callbacks for Objects, Arrays & Classes
363	 * but leave primitive properties and functions intact so that
364	 * the final object is fully defineComponent() style compatible.
365	 *
366	 * The default cloner is the native `structuredClone` (zero-dependency, handles
367	 * plain data, Map/Set/Date/typed arrays, circular refs). For defaults that
368	 * contain class instances or functions — which `structuredClone` cannot clone —
369	 * pass a `customCloner` such as lodash `cloneDeep`.
370	 *
371	 * @param defaults Regular object of default key -> values
372	 * @param typedProps Props declared in defineComponent() style with type and possibly required declared, but without default
373	 * @param customCloner Optional cloner used for object/array defaults (defaults to structuredClone)
374	 * @returns Props declared in defineComponent() style with all properties having default property declared.
375	 */
376	export function propsWithDefaults<T extends VuePropsObject>(
377	  defaults: Record<string, any>,
378	  typedProps: T,
379	  // Optional: Allows user to pass a custom cloner if structuredClone isn't enough
380	  customCloner?: (val: any) => any,
