  const a0 = await px(); await page.waitForTimeout(3000); const a1 = await px();
  console.log('speed@120 measured:', ((a1 - a0) / 3).toFixed(1), 'px/s');
  // drag the slider to 600 mid-glide
  await page.locator('.etm-speed input').evaluate((el) => { el.value = 600; el.dispatchEvent(new Event('input', { bubbles: true })); });
  await page.waitForTimeout(800);
  const b0 = await px(); await page.waitForTimeout(3000); const b1 = await px();
  console.log('speed@600 measured:', ((b1 - b0) / 3).toFixed(1), 'px/s');
  // shift+wheel scrubs the strip
  const box = await marquee.boundingBox();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  const s0 = await px();
  await page.keyboard.down('Shift');
  for (let i = 0; i < 6; i++) { await page.mouse.wheel(0, 240); await page.waitForTimeout(60); }
  await page.keyboard.up('Shift');
  await page.waitForTimeout(1200);
  const s1 = await px();
