  // plain vertical wheel must scroll the PAGE, not the strip
  const pageY0 = await page.evaluate(() => window.scrollY);
  const v0 = await px();
  for (let i = 0; i < 4; i++) { await page.mouse.wheel(0, 300); await page.waitForTimeout(60); }
  await page.waitForTimeout(700);
