      function tick(ts) {
        const m = new DOMMatrixReadOnly(getComputedStyle(inner).transform);
        samples.push({ t: ts, x: m.e });
        if (samples.length < 480) requestAnimationFrame(tick);
        else {
          const vs = [];
          for (let i = 5; i < samples.length; i++) {
            vs.push({ t: Math.round(samples[i].t - samples[0].t), v: Math.round(((samples[i-5].x - samples[i].x) / (samples[i].t - samples[i-5].t)) * 1000) });
          }
          resolve(vs);
        }
      }
      requestAnimationFrame(tick);
      // FORWARD deltaX wheel burst starting at ~500ms into the trace
      let sent = 0;
      const burst = setInterval(() => {
        el.dispatchEvent(new WheelEvent('wheel', { deltaX: 240, deltaY: 0, bubbles: true, cancelable: true }));
        if (++sent >= 6) clearInterval(burst);
      }, 55);
    }));
    const peakIdx = result.reduce((b, s, i) => s.v > result[b].v ? i : b, 0);
    const afterPeak = result.slice(peakIdx);
    console.log('peak:', result[peakIdx].v, 'px/s at', result[peakIdx].t + 'ms');
    console.log('min after peak:', Math.min(...afterPeak.map(s => s.v)), 'px/s (cruise 120)');
    console.log('decay profile:', afterPeak.filter((_, i) => i % 6 === 0).slice(0, 20).map(s => s.v).join(' '));
  } finally { await browser.close(); }
})().catch((e) => { console.error('FAIL', e.message); process.exit(1); });
