// ---- contention bench: 10 books measured through ONE pump while a rAF
// animation runs; report the animation's frame health ----
window.runContention = function runContention(books, paragraphsPerBook, batchSize) {
  return new Promise((resolve) => {
    const post = document.getElementById('post');
    const rig = document.createElement('div');
    rig.className = 'post measurer';
    post.appendChild(rig);

    // the victim: a rAF animation (stand-in for the marquee creep)
    const frames = [];
    let lastTs = null, animating = true;
    function animate(ts) {
      if (lastTs !== null) frames.push(ts - lastTs);
      lastTs = ts;
      if (animating) requestAnimationFrame(animate);
    }
    requestAnimationFrame(animate);

    // one queue across all books — interleaved fairly, one batch per slice
    const queue = [];
    for (let b = 0; b < books; b++) {
      for (let start = 0; start < paragraphsPerBook; start += batchSize) {
        queue.push({ book: b, start, end: Math.min(start + batchSize, paragraphsPerBook) });
      }
    }
    const heights = Array.from({ length: books }, () => []);
    let cursor = 0;
    const t0 = performance.now();

    function pump(deadline) {
      // process batches while the idle deadline allows; ALWAYS at least one
      do {
        if (cursor >= queue.length) return finish();
        const job = queue[cursor++];
        const chunks = [];
        for (let i = job.start; i < job.end; i++) chunks.push(paragraph(i + job.book * 7));
        rig.innerHTML = chunks.join('');
        const nodes = rig.children;
        for (let i = 0; i < nodes.length; i++) {
          heights[job.book].push(nodes[i].getBoundingClientRect().height);
        }
        rig.innerHTML = '';
      } while (deadline && deadline.timeRemaining() > 0 && cursor < queue.length);
      requestIdleCallback(pump, { timeout: 100 });
    }

    function finish() {
      const wall = performance.now() - t0;
      animating = false;
      rig.remove();
      const measured = heights.reduce((s, h) => s + h.length, 0);
      const sorted = [...frames].sort((a, b) => a - b);
      const p = (q) => +sorted[Math.floor(sorted.length * q)].toFixed(1);
      resolve({
        books, paragraphsPerBook, batchSize, measured,
        wallMs: Math.round(wall),
        frames: frames.length,
        frameMedian: p(0.5), frameP95: p(0.95), frameMax: +sorted[sorted.length - 1].toFixed(1),
        dropped: frames.filter((f) => f > 34).length, // >2 vsync = visible hitch
        badStalls: frames.filter((f) => f > 100).length,
      });
    }
    requestIdleCallback(pump, { timeout: 100 });
  });
};
'''
