const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  try {
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, reducedMotion: 'no-preference' });
    await page.goto('http://10.0.0.1:5174/examples/virtual-scroller', { waitUntil: 'load' });
    await page.waitForTimeout(2000);
    // marquee at new default 50
    await page.locator('.text-marquee').first().scrollIntoViewIfNeeded();
    await page.waitForTimeout(3000);
    const inner = page.locator('.text-marquee .virtual-scroller-inner--x').first();
    const px = async () => Math.abs(parseFloat((await inner.evaluate((el) => el.style.transform)).replace(/[^0-9.\-]/g, '')) || 0);
    const a0 = await px(); await page.waitForTimeout(4000); const a1 = await px();
    console.log('marquee default speed measured:', ((a1 - a0) / 4).toFixed(1), 'px/s (setting 50)');
    // vertical demo: slider present, drag to 40 px/s, transform advances faster
    await page.locator('.evs-frame').scrollIntoViewIfNeeded();
    await page.waitForTimeout(1500);
    const vInner = page.locator('.evs-frame .virtual-scroller-inner').first();
    const vPx = async () => Math.abs(parseFloat((await vInner.evaluate((el) => el.style.transform)).replace(/[^0-9.\-]/g, '')) || 0);
    const s0 = await vPx(); await page.waitForTimeout(3000); const s1 = await vPx();
    console.log('vertical default creep:', ((s1 - s0) / 3).toFixed(1), 'px/s (expect ~6.7)');
    await page.locator('.evs-speed input').evaluate((el) => { el.value = 40; el.dispatchEvent(new Event('input', { bubbles: true })); });
    await page.waitForTimeout(600);
    const s2 = await vPx(); await page.waitForTimeout(3000); const s3 = await vPx();
    console.log('vertical at slider 40:', ((s3 - s2) / 3).toFixed(1), 'px/s (expect ~40)');
    const label = await page.locator('.evs-speed-value').innerText();
    console.log('label shows:', label);
  } finally { await browser.close(); }
})().catch((e) => { console.error('FAIL', e.message); process.exit(1); });
"
